{
  "microservices": [
    {
      "microservice_name": "Booking Service",
      "responsibility": "Handles shipment registration with origin, destination, and delivery deadline; assigns unique tracking identifiers; manages route selection, destination changes, and replanning by coordinating with routing; maintains the shipment/cargo aggregate and its delivery status.",
      "communicates_with": ["Routing Service", "Handling Service", "Tracking Service"]
    },
    {
      "microservice_name": "Routing Service",
      "responsibility": "Computes and returns candidate routes (itineraries) compatible with a shipment's origin, destination, and delivery deadline via graph traversal over voyages and locations, informing when no feasible route exists.",
      "communicates_with": ["Booking Service"]
    },
    {
      "microservice_name": "Handling Service",
      "responsibility": "Records logistics events (receipt, loading, unloading, customs, pickup) across operational, integration/REST, mobile, and file-based channels; validates events against existing shipment, location, and trip; triggers shipment status recalculation while ensuring uniform rules and traceability of occurrence and recording times.",
      "communicates_with": ["Booking Service"]
    },
    {
      "microservice_name": "Tracking Service",
      "responsibility": "Provides shipment lookup by tracking identifier and presents current status, last known location, ETA, event history, plan adherence, route deviations, and consolidated administrative views grouped by business status.",
      "communicates_with": ["Booking Service", "Handling Service"]
    }
  ]
}

